// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.38;
contract C { uint x; constructor() { uint r; assembly ("memory-safe") { r := 42 } x=r; } function f() external view returns(uint) { return x; } }

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.38;
library L { function h() internal pure returns(uint r) { assembly ("memory-safe") { r := 42 } } } contract C { function f() external pure returns(uint) { return L.h(); } }

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.38;
contract C { function f() external pure { assembly ("memory-safe") { revert(0,0) } } }

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.38;
contract C { function f() external view returns(uint r) { assembly ("memory-safe") { r := gas() } } }

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.38;
contract C { function f() external pure returns(uint r) { assembly { r := 42 } } }

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.38;
contract C { function f() external returns(uint r) { assembly ("memory-safe") { r := callcode(1,0,0,0,0,0,0) } } }

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.38;
contract C { function f() external pure returns(uint r) { uint8 x; assembly ("memory-safe") { x := 0x142 r := x } } }

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.38;
contract C { function f() external pure returns(uint r) { bytes memory x = new bytes(32); assembly ("memory-safe") { r := x } } }

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.38;
contract C { uint x; function f() external returns(uint r) { assembly ("memory-safe") { mstore(0,42) sstore(0,mload(0)) log1(0,32,7) r := sload(0) } } }

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.38;
import "missing.sol"; contract C {}
